// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: adminCaller is the address that will be the msg.sender (admin) when calling setOwner,
    // newOwner is the address value passed into setOwner. The correct contract must set owner to newOwner
    // regardless of tx.origin; the mutant that uses tx.origin will differ for some inputs.
    function testFuzz_property(address adminCaller, address newOwner) public {
        // keep addresses wide but avoid zero-address for clarity
        vm.assume(adminCaller != address(0));
        vm.assume(newOwner != address(0));

        // The contract c's constructor set its owner and admin to the deployer (this contract),
        // but admin was set to msg.sender at contract creation (payable(msg.sender) assigned to admin private).
        // We need adminCaller to act as admin when calling setOwner; only the recorded admin may call.
        // However admin was set to address(this) at deployment of C in setUp() because new C() was called from this test contract.
        // To allow the fuzzed adminCaller to be the caller that new C() saw at its construction, we must deploy a fresh C
        // from a pranked account that matches adminCaller. So redeploy here under vm.prank.

        // Redeploy c so admin equals adminCaller
        vm.prank(adminCaller);
        C c2 = new C();

        // Now adminCaller is the admin of c2. Have adminCaller call setOwner passing newOwner.
        vm.prank(adminCaller);
        bool ok;
        try c2.setOwner(newOwner) returns (bool success) { ok = success; } catch { ok = false; }

        // Exactly one assertion: in the correct contract, after adminCaller calls setOwner(newOwner),
        // the public owner() must equal the supplied newOwner for all inputs. The mutant that assigns tx.origin
        // instead will cause owner() != newOwner for some choices where tx.origin != newOwner.
        assertTrue(ok && (c2.owner() == newOwner));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed parameters: adminCaller is a contract address that will call setOwner; newOwner is the address we ask to set.
    function testFuzz_property(address adminCaller, address newOwner) public {
        // Keep fuzzed addresses in wide, valid domains but avoid zero address for clarity
        vm.assume(adminCaller != address(0));
        vm.assume(newOwner != address(0));
        // Deploy a minimal caller contract that will call c.setOwner(newOwner) as msg.sender (so onlyAdmin check passes when this contract is admin)
        AdminCaller caller = new AdminCaller(c);

        // Make the deployed caller be the admin in c by impersonating the original admin (deployer) to set admin is private and was set to test deployer; here we need the caller to perform the setOwner call as the admin.
        // The C under test sets admin to the tx.origin at construction (original deployer). In setUp() we deployed c from this test address; to allow caller to pass onlyAdmin, we must have the contract's admin be the caller contract. Achieve this by having the test impersonate the admin and call a helper on the caller to invoke c through a prank where msg.sender equals admin (the admin is address(this) at c construction). However only the admin address set at construction can call setOwner; that was the test address. So we will have the test (admin) call into the caller contract and have that caller contract perform an external call to c.setOwner, so that inside c msg.sender == caller contract (not tx.origin).

        // In short: have the real admin (this test) call caller.callSetOwner(newOwner). That external call results in c.setOwner being invoked with msg.sender == caller (the contract), and tx.origin == this test address. This distinguishes correct behavior (owner == newOwner) from mutant (owner == tx.origin).

        // Ensure caller has some ETH to receive calls (not strictly necessary but safe)
        vm.deal(address(caller), 1 ether);

        // The test (which is the admin from construction) calls the caller contract, which in turn calls c.setOwner(newOwner).
        // Because the external call chain is: tx.origin == address(this) (EOA running the test), msg.sender inside c will be address(caller).
        // The correct contract sets owner = newOwner, but the mutant sets owner = tx.origin (address(this)).
        caller.callSetOwner(newOwner);

        // Observe c only via its public getter. Assert that c.owner() equals the provided newOwner.
        // This is true for the reference for all inputs; the mutant will fail when newOwner != tx.origin (which is almost always), so fuzzing finds such a case.
        assertTrue(c.owner() == newOwner);
    }
}

// Helper contract that receives a call from the admin (the test) and forwards to c.setOwner with itself as msg.sender.
contract AdminCaller {
    C immutable target;
    constructor(C _c) {
        target = _c;
    }
    function callSetOwner(address _owner) external {
        // forward call to target; msg.sender inside target will be this contract
        target.setOwner(_owner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the admin contract's address (as deployer of a helper) and the target owner address
    function testFuzz_property(address adminContractAddr, address newOwner) public {
        // Keep addresses non-zero to be in sensible domain
        vm.assume(adminContractAddr != address(0));
        vm.assume(newOwner != address(0));

        // Deploy a minimal admin-like contract that will call c.setOwner(newOwner)
        // We deploy it at a deterministic address by using CREATE (normal new) but ensure its constructor takes c and newOwner
        AdminCaller admin = new AdminCaller(c);

        // Give the admin contract some ETH so it is a contract caller (not an EOA) and has balance
        vm.deal(address(admin), 1 wei);

        // Make the admin contract call c.setOwner(newOwner)
        // Using try/catch to capture any revert and still observe owner
        bool ok;
        try admin.callSetOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assertion): for the correct contract, after the admin contract calls setOwner(newOwner), owner() equals the supplied newOwner.
        // The buggy mutant that writes owner = tx.origin can break this when tx.origin (the original EOA that initiated the tx) is not equal to newOwner.
        assertTrue(c.owner() == newOwner);
    }
}

// Helper contract that acts as an admin (a contract caller). It will call C.setOwner on behalf of its deployer.
contract AdminCaller {
    C public c;
    constructor(C _c) {
        c = _c;
    }
    function callSetOwner(address _owner) external {
        // forward the call to c as this contract
        c.setOwner(_owner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed parameters: adminCaller is the address that will act as msg.sender (must be admin),
    // candidateNewOwner is the address passed to setOwner. We must ensure adminCaller equals the contract's admin.
    function testFuzz_property(address adminCaller, address candidateNewOwner) public {
        // Keep domain wide but avoid the zero address for clearer semantics (still wide).
        vm.assume(adminCaller != address(0));
        // Ensure candidateNewOwner can be zero too; that's allowed by reference implementation.

        // The reference C sets admin = deployer (set in declaration to msg.sender at deployment).
        // In setUp() we deployed c with this test contract as msg.sender (an EOA simulated by forge),
        // so the stored admin is address(this) (the test contract). To exercise arbitrary adminCaller
        // we must deploy a thin forwarder contract whose address will be the admin and which will call setOwner
        // as a contract (so tx.origin differs from the forwarder). This enables distinguishing the mutant.

        // Deploy a forwarder that will call c.setOwner(candidateNewOwner). The forwarder will call as a contract.
        Forwarder f = new Forwarder(c);

        // The reference contract's admin is the deployer of C (this test contract). We need the admin to be f.
        // To achieve that, we must redeploy C with f as deployer. So deploy a fresh C with f as msg.sender.
        // Use vm.prank to make f the msg.sender during construction.
        vm.prank(address(f));
        C c2 = new C();

        // Now c2.admin == address(f). Have the forwarder call setOwner on c2 passing candidateNewOwner.
        // We want to observe that after the call, c2.owner() == candidateNewOwner for the reference.

        // Fund the forwarder so it can make the call (not strictly necessary for nonpayable but safe).
        vm.deal(address(f), 1 ether);

        // Make the forwarder perform the call as its own msg.sender (a contract). This makes tx.origin == address(this) (the test contract),
        // while msg.sender inside setOwner will be address(f). In the mutant, owner would be set to tx.origin (address(this)),
        // which will differ from candidateNewOwner for some fuzz inputs; the reference sets owner to candidateNewOwner.
        f.doSetOwner{value: 0}(c2, candidateNewOwner);

        // Single assertion: reference must have set owner to the supplied candidateNewOwner.
        // This is the general rule: after the admin (the forwarder contract) calls setOwner(newOwner), owner() == newOwner.
        assertTrue(c2.owner() == candidateNewOwner);
    }
}

// Minimal helper: a forwarder contract that calls C.setOwner on behalf of itself.
contract Forwarder {
    C public target;
    constructor(C _target) {
        target = _target;
    }
    // call setOwner on a given C instance with the provided address
    function doSetOwner(C cInstance, address newOwner) external payable {
        // call as this contract (msg.sender == address(this) in the callee)
        cInstance.setOwner(newOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: adminCaller is the address that will act as admin (must be non-zero), newOwner is the target owner
    function testFuzz_property(address adminCaller, address newOwner) public {
        // keep addresses in wide admissible domain
        vm.assume(adminCaller != address(0));
        vm.assume(newOwner != address(0));

        // We need the caller of setOwner to be the admin (the deployer was msg.sender in setUp -> c's admin is address(this) at construction time)
        // But contract C set admin = payable(msg.sender) at deployment; in setUp we deployed from this test contract, so the test contract (address(this)) is admin.
        // To exercise tx.origin vs param difference, we will deploy a thin forwarder contract whose runtime caller is the forwarder contract.

        // Deploy a forwarder from the fuzzer-chosen adminCaller: this makes tx.origin == adminExtern (EOA) while msg.sender inside C will be the forwarder.
        // We want the forwarder to act as admin (msg.sender inside setOwner), so we must make the forwarder be the admin recorded in C. But C's admin is set at construction to msg.sender (the test contract), so to make the call originate from an address that is equal to admin, we instead make the test contract delegate a call through a proxy pattern: we will have the test contract perform vm.prank(adminCaller) to create a ContractProxy which will BE the admin when calling setOwner. However, simpler: redeploy a fresh C instance from adminCaller so that that admin is adminCaller.

        // Deploy a fresh C with admin = adminCaller by using vm.prank to make deployment originate from adminCaller
        vm.startPrank(adminCaller);
        C c2 = new C();
        vm.stopPrank();

        // Now c2.admin == adminCaller (private) and owner initially == adminCaller (constructor set owner = msg.sender)
        // We want the call to setOwner to be made by the admin (adminCaller). To trigger the mutant difference, the adminCaller must be a contract so that tx.origin differs from the contract's intended _owner param in some cases.
        // The fuzzer provides adminCaller as an address (EOA with no code). We must create a contract that will act as the caller (so msg.sender is the contract) while tx.origin remains adminCaller. Deploy CallerHelper from adminCaller so that CallerHelper is a contract whose tx.origin==adminCaller when it makes the call into c2.

        // Deploy helper as if created by adminCaller
        vm.startPrank(adminCaller);
        CallerHelper helper = new CallerHelper();
        // Now have the helper call c2.setOwner(newOwner). This call will have msg.sender == address(helper) and tx.origin == adminCaller.
        helper.callSetOwner(address(c2), newOwner);
        vm.stopPrank();

        // The universal property: after the admin (here: helper acting on behalf of adminCaller) calls setOwner(newOwner), the contract's owner() must equal the provided newOwner.
        // Observe c2.owner() through its public getter. If the mutant set owner = tx.origin, owner() would equal adminCaller (tx.origin) instead of newOwner when adminCaller != newOwner.

        assertTrue(c2.owner() == newOwner);
    }
}

// Helper contract deployed by adminCaller; when it calls c.setOwner, tx.origin == adminCaller and msg.sender == address(this)
contract CallerHelper {
    function callSetOwner(address target, address newOwner) external {
        C(target).setOwner(newOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed param: an address that will attempt to call setOwner
    function testFuzz_property(address attacker, address newOwner) public {
        // keep addresses non-zero and not equal to deployer(admin) to explore meaningful space
        address admin = address(this); // note: in setUp, c was deployed by this test contract (msg.sender == address(this))
        vm.assume(attacker != address(0));
        vm.assume(newOwner != address(0));

        // Ensure attacker is not the admin (deployer). The correct contract requires only admin can call setOwner.
        vm.assume(attacker != admin);

        // Also ensure attacker is the current owner sometimes: first, confirm initial owner is admin (deployer)
        // Now, try to have attacker call setOwner to change owner to newOwner.
        bool ok;
        vm.prank(attacker);
        try c.setOwner(newOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }

        // General property: on the correct contract, only the admin (deployer) can call setOwner
        // therefore any non-admin caller's attempt must fail. We assert that here.
        // This assertion is satisfied by the reference for all inputs; the mutant that checks msg.sender==owner
        // will allow the current owner to succeed, breaking this assertion for some fuzzed inputs.
        assertTrue(ok == false);
    }
}
